#include "aegis/engine.hpp"
#include "aegis/bytes.hpp"
#include "aegis/diagnostics.hpp"
#include <algorithm>
#include <sstream>
#include <utility>
namespace aegis {
namespace { void ensure_end(ByteCursor& c){if(!c.empty())throw DecodeError("frame payload has trailing bytes");} }
EngineReport Engine::ingest(std::span<const std::uint8_t> in){return replay(decode_capture(in));}
EngineReport Engine::replay(const Capture& cap){EngineReport report;for(const auto& frame:cap.frames){try{apply(frame,report);++report.accepted;}catch(const DecodeError&e){++report.rejected;report.observations.push_back(e.what());audit_.append("reject",e.what());}}report.audits=audit_.size();report.health=health_report();return report;}
void Engine::apply(const Frame& f,EngineReport&r){ByteCursor c(f.payload);switch(f.kind){case FrameKind::register_subscriber:register_subscriber(c,r);break;case FrameKind::open_session:open_session(c,r);break;case FrameKind::define_route:define_route(c,r);break;case FrameKind::define_policy:define_policy(c,r);break;case FrameKind::stage_policy:stage_policy(c,r);break;case FrameKind::commit_policy:commit_policy(c,r);break;case FrameKind::quota_update:quota_update(c,r);break;case FrameKind::handover:handover(c,r);break;case FrameKind::extension:extension(c,r);break;case FrameKind::snapshot:snapshot(c,r);break;case FrameKind::rollback:rollback(c,r);break;case FrameKind::heartbeat:heartbeat(c,r);break;case FrameKind::close_session:close_session(c,r);break;case FrameKind::fragment:fragment(c,r);break;case FrameKind::audit:audit_.append("capture",c.short_text());ensure_end(c);break;case FrameKind::diagnostics:diagnostics(c,r);break;case FrameKind::checkpoint:checkpoint(c,r);break;case FrameKind::journal_stage:journal_stage(c,r);break;case FrameKind::checkpoint_rebuild:checkpoint_rebuild(c,r);break;case FrameKind::journal_finalize:journal_finalize(c,r);break;case FrameKind::trace_capture:trace_capture(c,r);break;case FrameKind::fragment_coalesce:fragment_coalesce(c,r);break;case FrameKind::trace_report:trace_report(c,r);break;case FrameKind::charge_clause:charge_clause(c,r);break;case FrameKind::charge_rewrite:charge_rewrite(c,r);break;case FrameKind::charge_report:charge_report(c,r);break;case FrameKind::replay_token:replay_token(c,r);break;case FrameKind::replay_pin:replay_pin(c,r);break;case FrameKind::replay_restore:replay_restore(c,r);break;case FrameKind::replay_verify:replay_verify(c,r);break;default:throw DecodeError("unknown frame kind");}}
void Engine::register_subscriber(ByteCursor&c,EngineReport&){Subscriber x{c.u32(),c.u32(),c.short_text(),true};ensure_end(c);subscribers_.upsert(std::move(x));audit_.append("subscriber","registered");}
void Engine::open_session(ByteCursor&c,EngineReport&){Session x; x.id=c.u32();x.subscriber_id=c.u32();x.route_id=c.u32();x.generation=c.u32();ensure_end(c);if(!subscribers_.find(x.subscriber_id))throw DecodeError("session subscriber unknown");sessions_.upsert(std::move(x));audit_.append("session","opened");}
void Engine::define_route(ByteCursor&c,EngineReport&){RouteRecord x{c.u32(),c.u32(),c.short_text(),c.u32(),true};ensure_end(c);routes_.upsert(std::move(x));route_index_.rebuild(routes_);audit_.append("route","defined");}
void Engine::define_policy(ByteCursor&c,EngineReport&){PolicyRule x; x.id=c.u32();x.revision=c.u32();x.route_id=c.u32();x.quota_limit=c.u32();x.priority=c.u16();x.label=c.short_text();ensure_end(c);policies_.stage(std::move(x));audit_.append("policy","defined");}
void Engine::stage_policy(ByteCursor&c,EngineReport&){auto sid=c.u32();auto pid=c.u32();ensure_end(c);auto*s=sessions_.find(sid);if(!s)throw DecodeError("policy target session unknown");if(!policies_.staged(pid))throw DecodeError("policy is not staged");s->policy_id=pid;audit_.append("policy","attached");}
void Engine::commit_policy(ByteCursor&c,EngineReport&){auto pid=c.u32();auto p=policies_.activate(pid);ensure_end(c);if(!p)throw DecodeError("missing staged policy");auto compiled=compiler_.compile(*p,route_index_);if(!compiled)throw DecodeError("policy route unknown");for(auto s:sessions_.values())if(s.policy_id==pid&&s.active){DispatchPlan plan;plan.compile(s.id,compiled);dispatch_.put(std::move(plan));extension_planner_.compile(s.id,p->revision,extensions_);charging_planner_.compile(s.id,p->revision,charges_);}audit_.append("policy","committed");}
void Engine::quota_update(ByteCursor&c,EngineReport&){auto sid=c.u32();auto used=c.u32();ensure_end(c);auto*s=sessions_.find(sid);if(!s)throw DecodeError("quota session unknown");s->usage+=used;auto p=policies_.active(s->policy_id);if(p&&s->usage>p->quota_limit)audit_.append("quota","limit exceeded");}
void Engine::handover(ByteCursor&c,EngineReport&){auto sid=c.u32();auto route=c.u32();auto gen=c.u32();ensure_end(c);auto*s=sessions_.find(sid);auto*rte=routes_.find(route);if(!s||!rte)throw DecodeError("handover reference missing");s->route_id=route;s->generation=gen;audit_.append("handover","moved");}
void Engine::extension(ByteCursor&c,EngineReport&){Extension x{c.u32(),c.u8(),c.short_text()};ensure_end(c);if(!sessions_.find(x.session_id))throw DecodeError("extension session unknown");extensions_.add(std::move(x));audit_.append("extension","stored");}
void Engine::snapshot(ByteCursor&c,EngineReport&){auto marker=c.u32();ensure_end(c);epoch_=std::max(epoch_,marker);audit_.append("snapshot","saved");}
void Engine::rollback(ByteCursor&c,EngineReport&){auto min=c.u32();ensure_end(c);routes_.compact(min);route_index_.rebuild(routes_);audit_.append("recovery","replayed");}
void Engine::heartbeat(ByteCursor&c,EngineReport&){auto sid=c.u32();ensure_end(c);if(!sessions_.find(sid))throw DecodeError("heartbeat session unknown");auto*d=dispatch_.find(sid);if(d)audit_.append("dispatch",d->audit_label());}
void Engine::close_session(ByteCursor&c,EngineReport&){auto sid=c.u32();ensure_end(c);sessions_.erase(sid);dispatch_.erase(sid);audit_.append("session","closed");}
void Engine::fragment(ByteCursor&c,EngineReport&){auto group=c.u32();auto part=c.short_text();ensure_end(c);fragment_store_.append(group,epoch_,part);fragments_.push_back(std::to_string(group)+":"+part);if(fragments_.size()>32)fragments_.erase(fragments_.begin());audit_.append("fragment","accepted");}
void Engine::diagnostics(ByteCursor&c,EngineReport&r){auto sid=c.u32();ensure_end(c);auto*d=dispatch_.find(sid);if(d)r.observations.push_back(d->audit_label());auto projection=extension_planner_.find(sid);if(projection)r.observations.push_back(render_extension_projection(extensions_,*projection));audit_.append("diagnostics","reported");}
void Engine::checkpoint(ByteCursor&c,EngineReport&){auto sid=c.u32();auto epoch=c.u32();auto count=c.u8();std::vector<std::uint32_t> markers;markers.reserve(count);for(std::uint8_t i=0;i<count;++i)markers.push_back(c.u32());ensure_end(c);if(!sessions_.find(sid))throw DecodeError("checkpoint session unknown");checkpoints_.persist(sid,epoch,std::move(markers));audit_.append("checkpoint","persisted");}
void Engine::journal_stage(ByteCursor&c,EngineReport&){auto sid=c.u32();auto epoch=c.u32();ensure_end(c);const auto* page=checkpoints_.find(sid);if(!page||page->epoch!=epoch)throw DecodeError("checkpoint journal reference missing");recovery_journal_.stage(*page);audit_.append("journal","staged");}
void Engine::checkpoint_rebuild(ByteCursor&c,EngineReport&){auto epoch=c.u32();ensure_end(c);checkpoints_.rebuild(epoch);audit_.append("checkpoint","rebuilt");}
void Engine::journal_finalize(ByteCursor&c,EngineReport&){auto sid=c.u32();auto epoch=c.u32();ensure_end(c);recovery_journal_.finalize_epoch(sid,epoch);audit_.append("journal","finalized");}
void Engine::trace_capture(ByteCursor&c,EngineReport&){auto sid=c.u32();auto group=c.u32();auto generation=c.u32();ensure_end(c);if(!sessions_.find(sid)||!dispatch_.find(sid))throw DecodeError("trace session is not active");if(!trace_window_.capture(sid,group,generation,fragment_store_))throw DecodeError("trace group is incomplete");audit_.append("trace","captured");}
void Engine::fragment_coalesce(ByteCursor&c,EngineReport&){auto generation=c.u32();ensure_end(c);fragment_store_.coalesce(generation);audit_.append("trace","coalesced");}
void Engine::trace_report(ByteCursor&c,EngineReport&r){auto sid=c.u32();auto group=c.u32();ensure_end(c);if(!sessions_.find(sid))throw DecodeError("trace session unknown");r.observations.push_back(trace_window_.render(sid,group));audit_.append("trace","reported");}
void Engine::charge_clause(ByteCursor&c,EngineReport&){auto sid=c.u32();auto kind=c.u8();auto value=c.short_text();ensure_end(c);auto* session=sessions_.find(sid);if(!session)throw DecodeError("charge session unknown");auto pending=policies_.staged(session->policy_id);auto active=policies_.active(session->policy_id);const auto revision=pending?pending->revision:(active?active->revision:0);if(revision==0)throw DecodeError("charge policy is unavailable");ChargeRepresentation representation;if(kind==static_cast<std::uint8_t>(ChargeRepresentation::binary))representation=ChargeRepresentation::binary;else if(kind==static_cast<std::uint8_t>(ChargeRepresentation::text))representation=ChargeRepresentation::text;else throw DecodeError("charge representation unknown");ChargeClause clause;clause.session_id=sid;clause.policy_revision=revision;clause.representation=representation;clause.payload.assign(value.begin(),value.end());charges_.upsert(std::move(clause));audit_.append("charge","staged");}
void Engine::charge_rewrite(ByteCursor&c,EngineReport&){auto sid=c.u32();auto revision=c.u32();ensure_end(c);auto active=policies_.active(sessions_.find(sid)?sessions_.find(sid)->policy_id:0);if(!active||active->revision!=revision)throw DecodeError("charge recovery policy mismatch");if(!charges_.rewrite_from_recovery(sid,revision))throw DecodeError("charge recovery clause mismatch");audit_.append("charge","rewritten");}
void Engine::charge_report(ByteCursor&c,EngineReport&r){auto sid=c.u32();ensure_end(c);auto projection=charging_planner_.find(sid);if(!projection)throw DecodeError("charge projection missing");r.observations.push_back(render_charge_projection(*projection));audit_.append("charge","reported");}
void Engine::replay_token(ByteCursor&c,EngineReport&){auto sid=c.u32();ReplayToken token;token.sequence=c.u64();token.nonce=c.u64();token.label=c.short_text();ensure_end(c);if(!sessions_.find(sid)||!dispatch_.find(sid))throw DecodeError("replay session is not active");replay_book_.insert(sid,std::move(token));audit_.append("replay","recorded");}
void Engine::replay_pin(ByteCursor&c,EngineReport&){auto sid=c.u32();auto sequence=c.u64();ensure_end(c);if(!replay_verifier_.pin(sid,sequence,replay_book_))throw DecodeError("replay token missing");audit_.append("replay","pinned");}
void Engine::replay_restore(ByteCursor&c,EngineReport&){auto minimum=c.u64();ensure_end(c);replay_book_.restore(minimum);audit_.append("replay","restored");}
void Engine::replay_verify(ByteCursor&c,EngineReport&r){auto sid=c.u32();ensure_end(c);r.observations.push_back(replay_verifier_.verify(sid));audit_.append("replay","verified");}
std::string Engine::health_report()const{std::ostringstream o;o<<"subscribers="<<subscribers_.values().size()<<" sessions="<<sessions_.values().size()<<" routes="<<routes_.values().size()<<" policies="<<policies_.values().size()<<" audit="<<audit_.size();return o.str();}
}
